from datetime import date; from decimal import Decimal; from types import SimpleNamespace; from unittest.mock import AsyncMock, MagicMock, patch; from uuid import uuid4; import pytest; from sqlalchemy.ext.asyncio import AsyncSession; from src.ledger import Account, AccountType, Direction, JournalEntry, JournalEntryStatus, JournalLine; from src.pricing.orm.market_data import FxRate; from src.reporting import ReportError, _aggregate_net_income_sql, generate_balance_sheet, generate_cash_flow, generate_income_statement, get_account_trend, get_category_breakdown
async def test_reporting_extreme_fallbacks_failure_reporting(db: AsyncSession, test_user_id):
    acc_usd = Account(user_id=test_user_id, name='USD Cash', type=AccountType.ASSET, currency='USD'); acc_inc = Account(user_id=test_user_id, name='USD Income', type=AccountType.INCOME, currency='USD'); db.add_all([acc_usd, acc_inc]); await db.commit(); await db.refresh(acc_usd); await db.refresh(acc_inc); entry = JournalEntry(user_id=test_user_id, entry_date=date(2025, 1, 15), memo='Salary', status=JournalEntryStatus.POSTED); db.add(entry); await db.flush(); db.add_all([JournalLine(journal_entry_id=entry.id, account_id=acc_usd.id, direction=Direction.DEBIT, amount=Decimal('100'), currency='USD', fx_rate=Decimal('1.00')), JournalLine(journal_entry_id=entry.id, account_id=acc_inc.id, direction=Direction.CREDIT, amount=Decimal('100'), currency='USD', fx_rate=Decimal('1.00'))]); await db.commit()
    with pytest.raises(ReportError, match='No FX rate available'): await generate_balance_sheet(db, test_user_id, as_of_date=date(2025, 1, 31), currency='SGD')
    with pytest.raises(ReportError, match='No FX rate available'): await generate_income_statement(db, test_user_id, start_date=date(2025, 1, 1), end_date=date(2025, 1, 31), currency='SGD')
async def test_reporting_trend_keys_coverage(db: AsyncSession, test_user_id): acc = Account(user_id=test_user_id, name='Bank', type=AccountType.ASSET, currency='SGD'); db.add(acc); await db.commit(); await db.refresh(acc); await get_account_trend(db, test_user_id, account_id=acc.id, period='weekly', currency='SGD'); await get_account_trend(db, test_user_id, account_id=acc.id, period='monthly', currency='SGD'); await get_account_trend(db, test_user_id, account_id=acc.id, period='daily', currency='SGD')
async def test_reporting_monthly_avg_fallback_coverage(db: AsyncSession, test_user_id): acc_usd = Account(user_id=test_user_id, name='USD Cash', type=AccountType.ASSET, currency='USD'); acc_inc = Account(user_id=test_user_id, name='USD Income', type=AccountType.INCOME, currency='USD'); db.add_all([acc_usd, acc_inc]); rate = FxRate(base_currency='USD', quote_currency='SGD', rate=Decimal('1.3'), rate_date=date(2025, 1, 31), source='test'); db.add(rate); await db.commit(); await db.refresh(acc_usd); await db.refresh(acc_inc); entry = JournalEntry(user_id=test_user_id, entry_date=date(2025, 1, 15), memo='Salary', status=JournalEntryStatus.POSTED); db.add(entry); await db.flush(); db.add_all([JournalLine(journal_entry_id=entry.id, account_id=acc_usd.id, direction=Direction.DEBIT, amount=Decimal('100'), currency='USD', fx_rate=Decimal('1.30')), JournalLine(journal_entry_id=entry.id, account_id=acc_inc.id, direction=Direction.CREDIT, amount=Decimal('100'), currency='USD', fx_rate=Decimal('1.30'))]); await db.commit(); await generate_income_statement(db, test_user_id, start_date=date(2025, 1, 1), end_date=date(2025, 1, 31), currency='SGD')
async def test_reporting_cash_flow_account_lookup_coverage(db: AsyncSession, test_user_id): from src.reporting import generate_cash_flow; acc = Account(user_id=test_user_id, name='Bank Cash', type=AccountType.ASSET, currency='SGD'); offset = Account(user_id=test_user_id, name='Owner Equity', type=AccountType.EQUITY, currency='SGD'); db.add_all([acc, offset]); await db.commit(); await db.refresh(acc); await db.refresh(offset); entry = JournalEntry(user_id=test_user_id, entry_date=date(2024, 12, 1), memo='Old', status=JournalEntryStatus.POSTED); db.add(entry); await db.flush(); db.add_all([JournalLine(journal_entry_id=entry.id, account_id=acc.id, direction=Direction.DEBIT, amount=Decimal('100'), currency='SGD'), JournalLine(journal_entry_id=entry.id, account_id=offset.id, direction=Direction.CREDIT, amount=Decimal('100'), currency='SGD')]); await db.commit(); await generate_cash_flow(db, test_user_id, start_date=date(2025, 1, 1), end_date=date(2025, 1, 31))
async def test_net_income_sql_raises_when_fx_rate_missing(db: AsyncSession, test_user_id):
    'AC5.6.7'; account = Account(user_id=test_user_id, name='USD Income', type=AccountType.INCOME, currency='USD'); asset = Account(user_id=test_user_id, name='USD Cash', type=AccountType.ASSET, currency='USD'); db.add_all([account, asset]); await db.flush(); entry = JournalEntry(user_id=test_user_id, entry_date=date(2025, 2, 1), memo='income', status=JournalEntryStatus.POSTED); db.add(entry); await db.flush(); db.add_all([JournalLine(journal_entry_id=entry.id, account_id=asset.id, direction=Direction.DEBIT, amount=Decimal('20'), currency='USD', fx_rate=Decimal('1.00')), JournalLine(journal_entry_id=entry.id, account_id=account.id, direction=Direction.CREDIT, amount=Decimal('20'), currency='USD', fx_rate=Decimal('1.00'))]); await db.commit()
    with pytest.raises(ReportError, match='No FX rate available for USD/SGD'): await _aggregate_net_income_sql(db, test_user_id, 'SGD', as_of_date=date(2025, 2, 1))
async def test_net_income_sql_uses_period_average_rate(db: AsyncSession, test_user_id): income_acc = Account(user_id=test_user_id, name='USD Salary', type=AccountType.INCOME, currency='USD'); asset_acc = Account(user_id=test_user_id, name='USD Cash', type=AccountType.ASSET, currency='USD'); db.add_all([income_acc, asset_acc]); await db.flush(); db.add_all([FxRate(base_currency='USD', quote_currency='SGD', rate=Decimal('1.30'), rate_date=date(2025, 1, 1), source='test'), FxRate(base_currency='USD', quote_currency='SGD', rate=Decimal('1.50'), rate_date=date(2025, 1, 31), source='test')]); entry = JournalEntry(user_id=test_user_id, entry_date=date(2025, 1, 15), memo='Salary Jan', status=JournalEntryStatus.POSTED); db.add(entry); await db.flush(); db.add_all([JournalLine(journal_entry_id=entry.id, account_id=asset_acc.id, direction=Direction.DEBIT, amount=Decimal('100'), currency='USD', fx_rate=Decimal('1.40')), JournalLine(journal_entry_id=entry.id, account_id=income_acc.id, direction=Direction.CREDIT, amount=Decimal('100'), currency='USD', fx_rate=Decimal('1.40'))]); await db.commit(); net_income, _ = await _aggregate_net_income_sql(db, test_user_id, 'SGD', as_of_date=date(2025, 1, 31), start_date=date(2025, 1, 1)); assert net_income == Decimal('140.00')
async def test_net_income_sql_detects_missing_fx_map_row() -> None:
    'AC5.6.7'; fake_db = MagicMock(); currency_result = MagicMock(); currency_result.all.return_value = [('USD',)]; agg_result = MagicMock(); agg_result.all.return_value = [SimpleNamespace(currency='EUR', type=AccountType.INCOME, direction=Direction.CREDIT, total=Decimal('10'))]; transfer_result = MagicMock(); transfer_result.scalars.return_value.all.return_value = []; discovery_result = MagicMock(); discovery_result.all.return_value = []; fake_db.execute = AsyncMock(side_effect=[transfer_result, discovery_result, currency_result, agg_result])
    with patch('src.reporting.extension._core.get_average_rate', new_callable=AsyncMock) as mock_avg, patch('src.reporting.extension._core.get_exchange_rate', new_callable=AsyncMock) as mock_spot:
        mock_avg.return_value = Decimal('1.35'); mock_spot.return_value = Decimal('1.35')
        with pytest.raises(ReportError, match='data consistency error'): await _aggregate_net_income_sql(fake_db, uuid4(), 'SGD', as_of_date=date(2025, 1, 31))
