    'AC-reporting.kpis.4 AC5.6.8'; account = Account(user_id=test_user_id, name='USD Trend', type=AccountType.ASSET, currency='USD'); offset = Account(user_id=test_user_id, name='USD Equity', type=AccountType.EQUITY, currency='USD'); db.add_all([account, offset]); await db.flush(); entry = JournalEntry(user_id=test_user_id, entry_date=date.today(), memo='trend', status=JournalEntryStatus.POSTED); db.add(entry); await db.flush(); db.add_all([JournalLine(journal_entry_id=entry.id, account_id=account.id, direction=Direction.DEBIT, amount=Decimal('5'), currency='USD', fx_rate=Decimal('1.00')), JournalLine(journal_entry_id=entry.id, account_id=offset.id, direction=Direction.CREDIT, amount=Decimal('5'), currency='USD', fx_rate=Decimal('1.00'))]); await db.commit()
    with patch('src.pricing.PrefetchedFxRates.prefetch', new_callable=AsyncMock, return_value=None), patch('src.pricing.PrefetchedFxRates.get_rate', return_value=None), pytest.raises(ReportError, match='No FX rate available for USD/SGD'): await get_account_trend(db, test_user_id, account_id=account.id, period='daily', currency='SGD')
